CREATE TABLE tenants(id TEXT PRIMARY KEY,name TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY,tenant TEXT NOT NULL REFERENCES tenants(id),email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL,recovery TEXT,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
CREATE TABLE sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires BIGINT NOT NULL);
CREATE INDEX idx_sessions_user ON sessions(user_id);
CREATE INDEX session_expiry ON sessions(expires);
CREATE TABLE records(id TEXT PRIMARY KEY,tenant TEXT NOT NULL REFERENCES tenants(id),kind TEXT NOT NULL,body JSONB NOT NULL,version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),created TEXT NOT NULL,updated TEXT NOT NULL,UNIQUE(tenant,id,kind));
CREATE INDEX tenant_records ON records(tenant,kind,created DESC);
CREATE TABLE audit(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tenant TEXT NOT NULL REFERENCES tenants(id),actor TEXT NOT NULL,action TEXT NOT NULL,record_id TEXT,created TEXT NOT NULL);
CREATE INDEX tenant_audit ON audit(tenant,id DESC);
CREATE TABLE counters(tenant TEXT NOT NULL REFERENCES tenants(id),prefix TEXT NOT NULL,value BIGINT NOT NULL,PRIMARY KEY(tenant,prefix));
CREATE TABLE idempotency(tenant TEXT NOT NULL REFERENCES tenants(id),key TEXT NOT NULL,result JSONB NOT NULL,PRIMARY KEY(tenant,key));
CREATE TABLE revisions(tenant TEXT NOT NULL,record_id TEXT NOT NULL,kind TEXT NOT NULL,version INTEGER NOT NULL,body JSONB NOT NULL,created TEXT NOT NULL,actor TEXT NOT NULL DEFAULT 'System',PRIMARY KEY(tenant,record_id,version),FOREIGN KEY(tenant,record_id,kind) REFERENCES records(tenant,id,kind));
CREATE TABLE import_sources(fingerprint TEXT PRIMARY KEY,imported TEXT NOT NULL,counts JSONB NOT NULL);
